using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = static_cast<int>(s.size());
    if (n < 2) {
        cout << -1 << '\n';
        return 0;
    }

    const vector<string> endings = {"00", "25", "50", "75"};
    long long answer = LLONG_MAX;

    for (const string& ending : endings) {
        for (int i = 0; i < n; ++i) {
            if (s[i] != ending[0]) continue;

            for (int j = 0; j < n; ++j) {
                if (i == j || s[j] != ending[1]) continue;

                long long moves = n - 1 - j;
                int tensPosition = i - (j < i);
                moves += n - 2 - tensPosition;

                int remaining = n - 2;
                if (remaining == 0) {
                    if (ending[0] == '0') continue;
                } else {
                    int leadingZeros = 0;
                    bool foundNonZero = false;

                    for (int k = 0; k < n; ++k) {
                        if (k == i || k == j) continue;
                        if (s[k] != '0') {
                            foundNonZero = true;
                            break;
                        }
                        ++leadingZeros;
                    }

                    if (!foundNonZero) continue;
                    moves += leadingZeros;
                }

                answer = min(answer, moves);
            }
        }
    }

    cout << (answer == LLONG_MAX ? -1 : answer) << '\n';
    return 0;
}

