#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();
    if (n < 2) {
        cout << -1 << '\n';
        return 0;
    }

    auto isDivisibleBy25 = [](const string& x) {
        int n = (int)x.size();
        if (n < 2) return false;
        string suffix = x.substr(n - 2);
        return suffix == "00" || suffix == "25" ||
               suffix == "50" || suffix == "75";
    };

    if (isDivisibleBy25(s)) {
        cout << 0 << '\n';
        return 0;
    }

    const vector<string> endings = {"00", "25", "50", "75"};
    int answer = INT_MAX;

    for (const string& ending : endings) {
        for (int first = 0; first < n; ++first) {
            if (s[first] != ending[0]) continue;

            for (int second = 0; second < n; ++second) {
                if (first == second || s[second] != ending[1]) continue;

                string current = s;
                int moves = 0;

                char last = current[second];
                current.erase(current.begin() + second);
                current.push_back(last);
                moves += n - 1 - second;

                int firstPosition = first - (first > second ? 1 : 0);
                char penultimate = current[firstPosition];
                current.erase(current.begin() + firstPosition);
                current.insert(current.end() - 1, penultimate);
                moves += n - 2 - firstPosition;

                if (current[0] == '0') {
                    int nonzero = -1;
                    for (int i = 1; i < n - 2; ++i) {
                        if (current[i] != '0') {
                            nonzero = i;
                            break;
                        }
                    }
                    if (nonzero == -1) continue;
                    moves += nonzero;
                }

                answer = min(answer, moves);
            }
        }
    }

    cout << (answer == INT_MAX ? -1 : answer) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

long long solve(string s, char a, char b) {
    const int n = static_cast<int>(s.size());
    if (n < 2) return LLONG_MAX;

    long long moves = 0;

    int pos = -1;
    for (int i = n - 1; i >= 0; --i) {
        if (s[i] == b) {
            pos = i;
            break;
        }
    }
    if (pos == -1) return LLONG_MAX;

    moves += n - 1 - pos;
    char digit = s[pos];
    s.erase(s.begin() + pos);
    s.push_back(digit);

    pos = -1;
    for (int i = n - 2; i >= 0; --i) {
        if (s[i] == a) {
            pos = i;
            break;
        }
    }
    if (pos == -1) return LLONG_MAX;

    moves += n - 2 - pos;
    digit = s[pos];
    s.erase(s.begin() + pos);
    s.insert(s.begin() + n - 2, digit);

    if (s[0] == '0') {
        pos = -1;
        for (int i = 1; i < n - 2; ++i) {
            if (s[i] != '0') {
                pos = i;
                break;
            }
        }
        if (pos == -1) return LLONG_MAX;
        moves += pos;
    }

    return moves;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    long long answer = LLONG_MAX;
    answer = min(answer, solve(s, '0', '0'));
    answer = min(answer, solve(s, '2', '5'));
    answer = min(answer, solve(s, '5', '0'));
    answer = min(answer, solve(s, '7', '5'));

    cout << (answer == LLONG_MAX ? -1 : answer) << '\n';
    return 0;
}

